  [`let gold = 7;\ngold -= 3;\nconsole.log(gold);`,["4","10","7"]],
  [`const p = { a: 1, b: 2 };\nconst k = "b";\nconsole.log(p[k]);`,["2","1","b"]],
  [`const gold = 3;\nconsole.log(gold >= 5 ? "Buy" : "Too poor");`,["Too poor","Buy","3"]],
  [`const bag = ["key"];\nbag.push("map");\nconsole.log(bag.length);`,["2","1","3"]]
