  [`const s = [{ n: "A", p: 5 }];\nconsole.log(s[0].n + s[0].p);`,["A5","5A","A 5"]],
  [`const s = [4, 1, 7];\ns.sort((a, b) => b - a);\nconsole.log(s[0]);`,["7","1","4"]],
  [`console.log([5, 6, 7, 8].slice(0, 3).length);`,["3","4","2"]],
  [`const s = [];\ns.push(10);\ns.push(20);\nconsole.log(s.length);`,["2","20","1"]],
  [`["Mo", "Ivy"].forEach((n, i) => console.log((i + 1) + "." + n));`,["1.Mo 2.Ivy","0.Mo 1.Ivy","Mo Ivy"]]
