        if(/[eE]/.test(src[j]||"")&&/[-+0-9]/.test(src[j+1]||"")){isD=true;j++;if(/[-+]/.test(src[j]))j++;while(/[0-9]/.test(src[j]))j++}
        const s=src.slice(i,j).replace(/_/g,"");
